  imp_read_loses: { en: 'loses to', es: 'pierde ante', ru: 'уступает', mk: 'губи од', de: 'unterliegt', fr: 'perd contre' },
  imp_read_headline_s: { en: 'Masterstroke — the field is yours to dictate.', es: 'Golpe maestro: el campo es tuyo.', ru: 'Мастерский ход — поле в вашей власти.', mk: 'Мајсторски потег — полето е твое.', de: 'Meisterstreich — das Feld gehorcht dir.', fr: 'Coup de maître — le terrain vous obéit.' },
  imp_read_headline_a: { en: 'Sound reasoning — the odds tilt your way.', es: 'Razonamiento sólido: las probabilidades te favorecen.', ru: 'Здравый расчёт — перевес на вашей стороне.', mk: 'Здраво расудување — предноста е на твоја страна.', de: 'Solides Kalkül — die Chancen neigen sich dir zu.', fr: 'Raisonnement solide — l’avantage penche vers vous.' },
  imp_read_headline_b: { en: 'Workable, but the edge is thin.', es: 'Viable, pero la ventaja es escasa.', ru: 'Приемлемо, но перевес невелик.', mk: 'Изводливо, но предноста е тенка.', de: 'Gangbar, doch der Vorsprung ist dünn.', fr: 'Jouable, mais l’avantage est mince.' },
  imp_read_headline_c: { en: 'Risky — you are fighting the ground and the enemy at once.', es: 'Arriesgado: luchas contra el terreno y el enemigo a la vez.', ru: 'Рискованно — вы бьётесь и с местностью, и с врагом.', mk: 'Ризично — се бориш и со теренот и со непријателот.', de: 'Riskant — du kämpfst gegen Gelände und Feind zugleich.', fr: 'Risqué — vous combattez le terrain et l’ennemi à la fois.' },
  imp_read_headline_d: { en: 'Reconsider — this plays straight into their strength.', es: 'Reconsidera: esto favorece justo su fuerza.', ru: 'Пересмотрите — это играет на их силу.', mk: 'Размисли повторно — ова оди право во нивната сила.', de: 'Überdenke es — das spielt genau ihrer Stärke zu.', fr: 'Reconsidérez — cela sert exactement leur force.' },
  imp_read_triangle_win: { en: 'Counters the enemy doctrine outright', es: 'Contrarresta de lleno la doctrina enemiga', ru: 'Прямо контрит доктрину врага', mk: 'Директно ја контрира непријателската доктрина', de: 'Kontert die feindliche Doktrin frontal', fr: 'Contre frontalement la doctrine ennemie' },
  imp_read_triangle_lose: { en: 'Walks into the enemy counter', es: 'Cae en el contraataque enemigo', ru: 'Попадает под контрудар врага', mk: 'Влегува во непријателскиот контранапад', de: 'Läuft in den feindlichen Konter', fr: 'Tombe dans le contre ennemi' },
  imp_read_triangle_mirror: { en: 'Mirror match — no doctrinal edge', es: 'Duelo en espejo: sin ventaja doctrinal', ru: 'Зеркальный бой — без доктринального перевеса', mk: 'Огледален дуел — без доктринарна предност', de: 'Spiegelduell — kein doktrinärer Vorteil', fr: 'Duel en miroir — aucun avantage doctrinal' },
  imp_read_charge_open: { en: 'Open ground gives cavalry room to build impetus', es: 'El terreno abierto da impulso a la caballería', ru: 'Открытое поле даёт коннице разгон', mk: 'Отворениот терен ѝ дава залет на коњицата', de: 'Offenes Gelände gibt der Reiterei Schwung', fr: 'Le terrain ouvert donne de l’élan à la cavalerie' },
  imp_read_charge_uphill: { en: 'Charging uphill blunts the impact', es: 'Cargar cuesta arriba mella el impacto', ru: 'Атака в гору гасит удар', mk: 'Јуриш нагоре го отапува ударот', de: 'Der Angriff bergauf bricht die Wucht', fr: 'Charger en côte émousse le choc' },
  imp_read_charge_river: { en: 'A river crossing scatters the charge', es: 'Cruzar un río dispersa la carga', ru: 'Переправа рассеивает атаку', mk: 'Преминот преку река го растура јуришот', de: 'Eine Flussüberquerung zersplittert den Angriff', fr: 'Une traversée de rivière disloque la charge' },
