  imp_read_hold_exposed: { en: 'Standing still on open plain surrenders the initiative', es: 'Quedarse quieto en llano cede la iniciativa', ru: 'Стоять на равнине — отдать инициативу', mk: 'Да стоиш на рамнина значи да ја предадеш иницијативата', de: 'Stillstehen in der Ebene gibt die Initiative preis', fr: 'Rester immobile en plaine cède l’initiative' },
